######################
### 1. SELECT TAXA ###
######################
# Arguments:
#   1. reltable: The abundances table generated by metaphlan
#   2. taxa_id: the identifier of the desired taxa -> k(ingdom), p(hyla), c(lass), o(rder), f(amily), g(enus), s(pecies), t (genome bin)
# Output:
#   A table with only the specified taxa level
# Description: 
#   This function take a table of relative abundancies, delete the NCBI ID column, keep only the rows corresponding to the specified taxa and clean the names

select_taxon <- function(reltable, taxa_id) {
  
  taxas <- c("k", "p", "c", "o", "f", "g", "s", "t")
  
  if(!(taxa_id %in% taxas)){
    stop(paste0("Taxa ID must be one of: ", paste(taxas, collapse = ", ")))
  }
  
  if("NCBI_tax_id" %in% colnames(reltable)){
    reltable <- reltable %>% 
      dplyr::select(-NCBI_tax_id)}
  
reltable %>% 
  dplyr::filter(str_detect(clade_name, if(taxa_id == "t") "t__[^|]*$" else paste0(ifelse(taxa_id == "k", "", "\\|"), taxa_id, "__[^|]*$"))) %>% 
  dplyr::mutate(ID = dplyr::case_when(
                  taxa_id == "t" ~ {sgb <- str_extract(clade_name, "t__[^|]*$");
                                    species <- str_extract(clade_name, "s__[^|]*");
                                    genus <- str_extract(clade_name, "g__[^|]*");
                                    parent <- dplyr::coalesce(species, genus);
                                    paste(parent, sgb, sep = "_")},
                  TRUE ~ {x <- str_extract(clade_name, paste0(ifelse(taxa_id == "k", "", "\\|"), taxa_id, "__[^|]*$")); str_replace_all(x, "\\|", "")})) %>% 
  dplyr::select(-clade_name) %>%
  dplyr::relocate(ID, .before = 1)
}

###############################
### 2. FILTER NEAR-ZERO VAR ###
###############################
# Arguments:
#   1. reltable: The abundances table generated by metaphlan
#   2. scale_by_100: If TRUE divide the abundances by 100. Default set to FALSE
#   3. ID_column: The column with the clade name. Default to "ID"
# Output:
#   A dataframe with only the features that keeps only features with a non near-zero variance
# Description:
#   This function take a table of relative abundancies, remove the features with a NearZeroVar and return a table with the filtered rows (Scaled or not)

filter_nzv <- function(relTable, scale_by_100 = FALSE, ID_column = "ID") {
  
  if (ID_column %in% colnames(relTable)) {
    relTable <- relTable %>%
      tibble::column_to_rownames(ID_column)
  }
  
  nearzerovar_features <- caret::nearZeroVar(t(relTable))
  
  if (length(nearzerovar_features) > 0) {
    relTable_filtered <- relTable[-nearzerovar_features, , drop = FALSE]
  } else {
    relTable_filtered <- relTable
  }
  
  if (scale_by_100) {
    message("Scaling by 100")
    relTable_filtered <- relTable_filtered / 100
  }
  
  return(relTable_filtered)
}

##
beta_test <- function(variable, beta_bray, metadata, permutations = 999) {
    
    # PERMANOVA
    formula <- as.formula(paste("beta_bray ~", variable))
    adonis_res <- vegan::adonis2(formula, data = metadata, permutations = permutations)
    
    # PERMDISP
    group <- metadata[[variable]]
    dispersion <- vegan::betadisper(beta_bray, group = group)
    dispersion_perm <- vegan::permutest(dispersion, permutations = permutations)
    
    # Output
    tibble::tibble(Variable = variable,
                   N = sum(!is.na(group)),
                   Groups = dplyr::n_distinct(group, na.rm = TRUE),
                   PERMANOVA_R2 = adonis_res$R2[1],
                   PERMANOVA_F = adonis_res$F[1],
                   PERMANOVA_p = adonis_res$`Pr(>F)`[1],
                   PERMDISP_F = dispersion_perm$tab$F[1],
                   PERMDISP_p = dispersion_perm$tab$`Pr(>F)`[1])
}

## pairwise beta_test
beta_test_pairwise <- function(variable, beta_bray, metadata, permutations = 999) {
    group <- metadata[[variable]]

    # PERMANOVA
    adonis_res <- OmicFlow::pairwise_adonis(
      x = beta_bray, 
      groups = group,
      perm = permutations
    )
    
    # PERMDISP
    dispersion <- vegan::betadisper(beta_bray, group = group)
    dispersion_perm <- vegan::permutest(dispersion, permutations = permutations)
    
    # Output
    tibble::tibble(
      Groups = c(paste0(variable, ": ", adonis_res$pairs), paste0(variable, ": betadisper")),
      PERMANOVA_F = c(adonis_res$F, dispersion_perm$tab$F[1]),
      PERMANOVA_p = c(adonis_res$p.value, dispersion_perm$tab$`Pr(>F)`[1])
    )
}
